    "performance": "思考智能 (調)ti-Ⅳ-1能依據已知的自然科學知識概念，經由自我或團體探索與討論的過程，想像當使用的觀察方法或實驗方法改變時，其結果可能產生的差異；並能嘗試在指導下以創新思考和方法得到新的模型、成品或結果。 (調)tr -Ⅳ-1 能將所習得的知識正確的連結到所觀察到的自然現象及實驗數據，並推論出其中的關聯，進而運用習得的知識來解釋自己論點的正確性。 (調)tc-Ⅳ-1 能依據已知的自然科學知識與概念，對自己蒐集與分類的科學數據，抱持合理的懷疑態度，並對他人的資訊或報告，提出自己的看法或解釋。 問題解決 (調)po-Ⅳ-2 能辨別適合科學探究或適合以科學方式尋求解決的問題（或假說），並能依據觀察、蒐集資料、閱讀、思考、討論等，提出適宜探究之問題。 (調)pe-Ⅳ-2能正確安全操作適合學習階段的物品、器材儀器、科技設備及資源。能進行客觀的質性觀察或數值量測並詳實記錄。 (調)pa-Ⅳ-1能分析歸納、製作圖表、使用資訊及數學等方法，整理資訊或數據。 (調)pc-Ⅳ-1能理解同學的探究過程和結果（或經簡化過的科學報告），提出合理而且具有根據的疑問或意見。並能對問題、探究方法、證據及發現，彼此間的符應情形，進行檢核並提出可能的改善方案。 科學的態度與本質 (調)ai-Ⅳ-1 動手實作解決問題或驗證自己想法，而獲得成就感。 (調)ai-Ⅳ-2透過與同儕的討論，分享科學發現的樂趣。 (調)ah-Ⅳ-2應用所學到的科學知識與科學探究方法，幫助自己做出最佳的決定。 (調)an-Ⅳ-2分辨科學知識的確定性和持久性，會因科學研究的時空背景不同而有所變化。 (調)an-Ⅳ-3 體察到科學家們具有堅毅、嚴謹和講求邏輯的特質，也具有好奇心、求知慾和想像力",
    "content": "(調)Bd-Ⅳ-1 生態系中的能量來源是太陽，能量會經由食物鏈在不同生物間流轉。 (調)Bd-Ⅳ-2 在生態系中，碳元素會出現在不同的物質中（例如：二氧化碳、葡萄糖），在生物與無生物間循環使用。 (調)Bd-Ⅳ-3 生態系中，生產者、消費者和分解者共同促成能量的流轉和物質的循環。 (調)Da-Ⅳ-4 細胞會進行細胞分裂，染色體在分裂過程中會發生變化。 (調)Db-Ⅳ-4 生殖系統（以人體為例）能產生配子進行有性生殖，並且有分泌激素的功能。 (調)Db-Ⅳ-7 花的構造中，雄蕊的花藥可產生花粉粒，花粉粒內有精細胞；雌蕊的子房內有胚珠，胚珠內有卵細胞。 (調)Db-Ⅳ-8 植物體的分布會影響水在地表的流動，也會影響氣溫和空氣品質。 (調)Fc-Ⅳ-1 生物圈內含有不同的生態系。生態系的生物因子，其組成層次由低到高為個體、族群、群集。 (調)Ga-Ⅳ-1 生物的生殖可分為有性生殖與無性生殖，有性生殖產生的子代其性狀和親代差異較大。 (調)Ga-Ⅳ-4 遺傳物質會發生變異，其變異可能造成性狀的改變，若變異發生在生殖細胞可遺傳到後代。 (調)Ga-Ⅳ-5 生物技術的進步，有助於解決農業、食品、能源、醫藥，以及環境相關的問題，但也可能帶來新問題。 (調)Ga-IV-2 人類的性別主要由性染色體決定。 (調)Ga-IV-3 人類的ABO血型是可遺傳的性狀。 (調)Ga-IV-6 孟德爾遺傳研究的科學史。 (調)Gb-Ⅳ-1 從地層中發現的化石，可知地球上曾經存在許多的生物，但有些生物已經消失了，例如：三葉蟲、恐龍等。 (調)Gc-Ⅳ-1 依據生物形態與構造的特徵，可以將生物分類。 (調)Gc-Ⅳ-2 地球上有形形色色的生物，在生態系中擔任不同的角色，發揮不同的功能，有助於維持生態系的穩定。 (調)Gc-Ⅳ-3 人的體表和體內有許多微生物，有些微生物對人體有利，有些則有害。 (調)INc-Ⅳ-6 從個體到生物圈是組成生命世界的巨觀尺度。 (調)INg-Ⅳ-5 生物活動會改變環境，環境改變之後也會影響生物活動。 (調)La-Ⅳ-1 隨著生物間、生物與環境間的交互作用，生態系中的結構會隨時間改變，形成演替現象。 (調)Lb-Ⅳ-1 生態系中的非生物因子會影響生物的分布與生存，環境調查時常需檢測非生物因子的變化。 (調)Lb-Ⅳ-2 人類活動會改變環境，也可能影響其他生物的生存。 (調)Lb-Ⅳ-3 人類可採取行動來維持生物的生存環境，使生物能在自然環境中生長、繁殖、交互作用，以維持生態平衡。 (調)Ma-Ⅳ-1 生命科學的進步，有助於解決社會中發生的農業、食品、能源、醫藥，以及環境相關的問題。 (調)Ma-Ⅳ-2 保育工作不是只有科學家能夠處理，所有的公民都有權利及義務，共同研究、監控及維護生物多樣性。 (調)Ma-Ⅳ-5各種本土科學知能（含原住民族科學與世界觀）對社會、經濟環境及生態保護之啟示。 (調)Mb-Ⅳ-1 生物技術的發展是為了因應人類需求，運用跨領域技術來改造生物。發展相關技術的歷程中，也應避免對其他生物以及環境造成過度的影響。 (調)Me-Ⅳ-1 環境汙染物對生物生長的影響及應用。 (調)Me-Ⅳ-6 環境汙染物與生物放大的關係。 (調)Nb-Ⅳ-1 全球暖化對生物的影響。",
