    "performance": "一、自然領域課綱學習表現 （一）探究能力 (調)ti-Ⅳ-1 能依據已知的自然科學知識概念，經由自我或團體探索與討論的過程，想像當使用的觀察方法或實驗方法改變時，其結果可能產生的差異；並能嘗試在指導下以創新思考和方法得到新的模型、成品或結果。 (調)tr-Ⅳ-1 能將所習得的知識正確的連結到所觀察到的自然現象及實驗數據，並推論出其中的關聯，進而運用習得的知識來解釋自己論點的正確 性。 (調)tc-Ⅳ-1 能依據已知的自然科學知識與概念，對自己 蒐集與分類的科學數據，抱持合理的懷疑態 度，並對他人的資訊或報告，提出自己的看法或解釋。 (調)tr-Ⅳ-1 能將所習得的知識正確的連結到所觀察到的自然現象及實驗數據，並推論出其中的關聯，進而運用習得的知識來解釋自己論點的正確性。 (調)po-Ⅳ-1 能從學習活動、日常經驗及科技運用、自然環境、書刊及網路媒體中，進行各種有計畫的觀察，進而能察覺問題。 (調)pe-Ⅳ-2 能正確安全操作適合學習階段的物品、器材儀器、科技設備與資源。能進行客觀的質性觀測或數值量測並詳實記錄。 (調)pa-Ⅳ-1 能分析歸納、製作圖表、使用資訊與數學等方法，整理資訊或數據。 (調)pc-Ⅳ-2 能利用口語、影像（如攝影、錄影）、文字與圖案、繪圖或實物、科學名詞、數學公式、模型或經教師認可後以報告或新媒體形式表達完整之探究過程、發現與成果、價值、限制和主張等。視需要，並能摘要描述主要過程、發現和可能的運用。 （二）科學的態度與本質 (調)ai-Ⅳ-1 動手實作解決問題或驗證自己想法，而獲得成就感。 (調)ai-Ⅳ-2 透過分享獲得成就感與學習樂趣，提升自我學習效能。 (調)ai-Ⅳ-3 透過所學到的科學知識和科學探索的各種方 法，解釋自然現象發生的原因，建立科學學習的自信心。 (調)an-Ⅳ-1 察覺到科學的觀察、測量和方法是否具有正當性是受到社會共同建構的標準所規範。 (調)an-Ⅳ-2 分辨科學知識的確定性和持久性會因科學研究時空背景不同而有所變化。 (調)an-Ⅳ-3 經典範學習體察到科學家們具有堅毅、嚴謹和講求邏輯的特質，也具有好奇心、求知慾和想像力。",
